window.RAI_PAGES = {"index.html":{"title":"Accueil · Rai Netero","main":"<main><section class=\"hero\"><div class=\"hero-inner\"><div><div class=\"eyebrow\"><i></i>Chroniques d'un pourfendeur</div><h1><span class=\"hero-title-line glow\">RAI</span><span class=\"hero-title-line\">NETERO</span></h1><p class=\"hero-blurb\">Il existe des noms que l'on reçoit à la naissance, et d'autres que l'on passe une vie entière à essayer de mériter.<br/><br/>Entre la pluie du Sentier Tonnerre et le fracas de la Foudre, voici l'histoire d'un garçon qui apprit qu'on ne pouvait pas tout esquiver.</p><a class=\"btn\" href=\"histoire.html\">DÉCOUVRIR SON HISTOIRE <span aria-hidden=\"true\">↗</span></a></div><figure class=\"hero-image\"><img alt=\"Rai en mouvement, drapé dans son manteau blanc\" src=\"assets/rai-action.jpg\"/></figure></div><span class=\"vertical-kanji\">雷の呼吸 · KAMINARI NO KOKYŪ</span></section><section class=\"layout\"><div class=\"intro-grid\"><figure class=\"intro-visual\"><img alt=\"Paysage lumineux du Sentier Tonnerre\" src=\"assets/sentier-lumineux.jpg\"/></figure><div class=\"intro-panel\"><div class=\"eyebrow\"><i></i>Une vie entre deux orages</div><h2>L'héritage ne fait pas l'homme.</h2><p>On lui a souvent raconté la légende de Beyond Netero. Pourtant, Rai a grandi avec de plus grandes préoccupations : Mémé Turbo, les beignets et une pluie impossible à esquiver.</p><p>Puis un soir, le village du Sentier Tonnerre a cessé de ressembler à celui de son enfance.</p><div class=\"signature\">« Aujourd'hui, je cours pour que d'autres puissent encore regarder la pluie tomber. »</div><div style=\"margin-top:28px\"><a class=\"btn\" href=\"identite.html\">CONSULTER SA FICHE ↗</a></div></div></div></section></main>"},"identite.html":{"title":"Identité · Rai Netero","main":"<main><section class=\"page-hero\" style=\"--hero-image:url('assets/ciel-couchant.jpg')\"><div class=\"page-hero-content\"><div class=\"eyebrow\"><i></i>01 / Identité</div><h1>Identité</h1><p class=\"subtitle\">Un nom, un héritage et un sabreur qui cherche sa propre voie.</p></div></section><div class=\"layout\"><div class=\"section-head\"><div class=\"eyebrow\">Fiche personnelle</div><h2>Rai Netero <span style=\"color:#dfc790\">雷</span></h2></div><div class=\"info-grid\"><div class=\"info-item\"><div class=\"label\">Fiche de</div><strong>Capric</strong><div class=\"small\">Identifiant Discord : 389172282452344833</div></div><div class=\"info-item\"><div class=\"label\">Nom / prénom</div><strong>Netero Rai</strong><div class=\"small\">Écriture occidentale : Rai Netero</div></div><div class=\"info-item\"><div class=\"label\">Âge</div><strong>21 ans</strong><div class=\"small\">Sélection Finale à 18 ans</div></div><div class=\"info-item\"><div class=\"label\">Espèce</div><strong>Humain</strong><div class=\"small\">Pourfendeur de démons</div></div><div class=\"info-item\"><div class=\"label\">Grade souhaité</div><strong>Tsuchinoe</strong><div class=\"small\">Sixième rang de l’Armée</div></div><div class=\"info-item\"><div class=\"label\">Souffle</div><strong>Foudre</strong><div class=\"small\">Kaminari no Kokyū</div></div><div class=\"info-item\"><div class=\"label\">Taille / poids</div><strong>1,68 m · 59 kg</strong><div class=\"small\">Gabarit élancé et athlétique</div></div><div class=\"info-item\"><div class=\"label\">Sexe</div><strong>Masculin</strong></div><div class=\"info-item\"><div class=\"label\">Origine</div><strong>Sentier Tonnerre</strong><div class=\"small\">Village natal</div></div><div class=\"info-item\"><div class=\"label\">Maître</div><strong>Izanagi</strong><div class=\"small\">Ancien pourfendeur</div></div><div class=\"info-item\"><div class=\"label\">Orientation</div><strong>Hétérosexuel</strong></div><div class=\"info-item\"><div class=\"label\">Surnom</div><strong>L’Éclair jaune</strong></div><div class=\"info-item\"><div class=\"label\">Thème musical</div><strong>Izanami · Kirin</strong><div class=\"small\">Écouter avec le lecteur musical en bas de page</div></div></div><div class=\"two-col\"><div class=\"body-copy\"><h3>Ses racines</h3><p>Rai est le dernier descendant de la lignée des Netero qu’il connaisse. Élevé par sa grand-mère, surnommée Mémé Turbo, il a grandi à l’ombre d’une vieille légende familiale : celle de Beyond, un sabreur qui aurait consacré dix années à son art sur la montagne du Tonnerre.</p><p>Après la destruction de son village à seize ans, il a été recueilli et formé par Izanagi, ancien pourfendeur. Il a réussi la Sélection Finale à dix-huit ans et a progressé dans l’Armée au fil des missions.</p></div><div class=\"note\"><strong>Le Sentier Tonnerre</strong><br/>Entre les rizières et les averses, Rai a grandi avec les histoires de Beyond et les courses impossibles de Mémé Turbo. Il y a appris à aimer la pluie bien avant de comprendre ce qu’elle pouvait emporter.</div></div><div class=\"subfooter\"><a href=\"psyche.html\">SUIVANT — SA PSYCHÉ ↗</a></div></div></main>"},"psyche.html":{"title":"Psyché · Rai Netero","main":"<main><section class=\"page-hero\" style=\"--hero-image:url('assets/pluie-fleurs.jpg')\"><div class=\"page-hero-content\"><div class=\"eyebrow\"><i></i>02 / Caractère</div><h1>Psyché</h1><p class=\"subtitle\">Sous le calme d’un garçon distrait, une volonté qui se construit à l’épreuve de la perte.</p></div></section><div class=\"layout\"><div class=\"two-col\"><div class=\"body-copy\"><div class=\"eyebrow\">Portrait moral</div><h2>Entre douceur<br/>et obstination.</h2><p>Rai est un jeune homme attentif aux petites choses, souvent perdu dans ses pensées et capable de poursuivre les idées les plus improbables avec une obstination désarmante. Les autres le trouvent parfois étrange ; lui trouve surtout que le monde manque un peu d’imagination.</p><p>Il n’a jamais été naturellement à l’aise au milieu des groupes. Son humour discret lui permet néanmoins de créer des liens, et sa gentillesse se manifeste davantage dans ce qu’il fait pour les autres que dans de grandes déclarations.</p><p>Il éprouve un attachement très fort à ceux qui lui témoignent de l’affection. La disparition de Mémé Turbo l’a rendu sensible aux séparations et à l’idée d’arriver trop tard. Il lui arrive de masquer cette peur derrière une remarque légère.</p><p>Sa colère envers les démons n’a pas disparu. Il s’efforce de ne pas lui laisser décider à sa place. C’est l’une des leçons les plus difficiles que lui a enseignées Izanagi : sauver une vie vaut davantage que remporter une victoire spectaculaire.</p></div><figure class=\"poster\"><img alt=\"Rai Netero sous sa capuche blanche\" data-gif-portrait=\"\" src=\"assets/portrait-logo.png\"/><figcaption>Portrait de Rai · 雷</figcaption></figure></div><div class=\"quotes\"><div class=\"quote-card\"><h3>Qualités</h3><p>Empathique, consciencieux lorsqu'une vie est en jeu, loyal, persévérant, capable d'autodérision et ouvert à l'apprentissage.</p></div><div class=\"quote-card\"><h3>Failles</h3><p>Difficulté à s'intégrer, tendance à se culpabiliser après un échec, peur de perdre à nouveau un proche, impulsivité lorsqu'il est blessé émotionnellement.</p></div><div class=\"quote-card\"><h3>Convictions</h3><p>Protéger avant de vaincre. Ne pas laisser la peur ou la haine dicter un combat. Avancer même lorsqu'il est impossible d'éviter la pluie.</p></div></div><div class=\"separator\"></div><div class=\"two-col\"><div class=\"body-copy\"><h3>Rapport au nom Netero</h3><p>Rai admire la légende de Beyond, sans chercher désormais à reproduire ses exploits. Il commence à comprendre qu'honorer un héritage ne signifie pas vivre à la place d'un autre.</p></div><div class=\"body-copy\"><h3>Rituels et petites manies</h3><p>Il observe encore les averses, se rappelle parfois son ancien jeu consistant à esquiver les gouttes et s’arrête volontiers acheter des beignets lorsqu’une échoppe lui évoque sa grand-mère. Il lui arrive d’en acheter deux, par pure habitude.</p></div></div><div class=\"music-note\"><h3>Thème musical</h3><p>Izanami · Kirin</p></div><div class=\"subfooter\"><a href=\"histoire.html\">SUIVANT — SON HISTOIRE ↗</a></div></div></main>"},"histoire.html":{"title":"Histoire · Rai Netero","main":"<main><section class=\"page-hero\" style=\"--hero-image:url('assets/montagne-orage.jpg')\"><div class=\"page-hero-content\"><div class=\"eyebrow\"><i></i>03 / Histoire personnelle</div><h1>Les cinq pluies</h1><p class=\"subtitle\">De la légende d’un ancêtre à la naissance d’un pourfendeur. Cinq chapitres sous le ciel du Sentier Tonnerre.</p></div></section><div class=\"layout\"><div class=\"eyebrow\"><i></i>Accès direct aux chapitres</div><div class=\"chapter-nav\"><a href=\"histoire.html#heritage\"><span class=\"num\">01 / 05</span><strong>Héritage</strong><small>Le poids d’un nom</small></a><a href=\"histoire.html#enfance\"><span class=\"num\">02 / 05</span><strong>Enfance</strong><small>Le village du Sentier Tonnerre</small></a><a href=\"histoire.html#encore-le-tonnerre\"><span class=\"num\">03 / 05</span><strong>Encore le tonnerre</strong><small>Quand la pluie devint rouge</small></a><a href=\"histoire.html#kaminari\"><span class=\"num\">04 / 05</span><strong>Kaminari</strong><small>Apprendre à avancer sous la pluie</small></a><a href=\"histoire.html#apres-lorage\"><span class=\"num\">05 / 05</span><strong>Après l’orage</strong><small>Les sept nuits et les premières missions</small></a></div><div class=\"reader-tag\">« Personne ne peut esquiver toutes les gouttes d’un orage. »</div><section class=\"chapter\" id=\"heritage\"><div class=\"chapter-banner\" style=\"background-image:url('assets/ciel-couchant.jpg')\"><div><div class=\"chapter-index\">01 / 05</div><h2>Héritage</h2><p>Le poids d’un nom</p></div></div><article class=\"story-text\"><p>Mon nom est Rai Netero.</p>\n<p>Il existe des noms que l'on reçoit à la naissance, et d'autres que l'on passe une vie entière à essayer de mériter.</p>\n<p>Le mien appartient à la seconde catégorie.</p>\n<p>Netero.</p>\n<p>Quelques syllabes, tout au plus. Pourtant, derrière elles se cachent des générations d'hommes et de femmes, des traditions, des espoirs et, surtout, le souvenir d'un homme dont le nom résonne encore dans les histoires de notre famille.</p>\n<p><strong>Beyond Netero.</strong></p>\n<p>Je n'ai jamais connu cet homme. Je ne sais même pas quelle part de vérité subsiste dans les récits que ma grand-mère me racontait, enfant. Mais s'il est une histoire que je pourrais réciter les yeux fermés, c'est bien la sienne.</p>\n<p>On raconte qu'autrefois, Beyond était un sabreur ayant consacré sa vie à la maîtrise de son art. Pourtant, malgré les années passées à manier la lame, quelque chose lui manquait encore.</p>\n<p>Alors, un jour, il prit une décision.</p>\n<p>Il gravit la montagne du Tonnerre, le plus haut sommet qui surplombait notre village, et s'y retira, seul.</p>\n<p>Il y demeura dix années.</p>\n<p><strong>Dix années.</strong></p>\n<p>Dix printemps à voir renaître la montagne. Dix étés sous un soleil accablant. Dix automnes à regarder les feuilles mourir. Dix hivers à affronter le froid.</p>\n<p>Chaque jour, le même rituel.</p>\n<p>Il se tenait droit, prenait son sabre, réglait sa respiration, puis exécutait une coupe.</p>\n<p>Une seule.</p>\n<p>Puis une autre.</p>\n<p>Et encore une autre.</p>\n<p>Il recommençait jusqu'à l'épuisement. Le lendemain, il reprenait. Et le surlendemain aussi.</p>\n<p>Les jours devinrent des mois. Les mois devinrent des années.</p>\n<p>Ce qui, autrefois, exigeait toute sa concentration devint peu à peu aussi naturel que respirer. Le sabre ne lui semblait plus être un objet étranger qu'il devait apprendre à maîtriser. Il était devenu le prolongement de gestes répétés des milliers de fois.</p>\n<p>Mais le plus étrange, dans cette histoire, n'était pas la durée de son entraînement.</p>\n<p>C'était sa raison.</p>\n<p>Beyond ne cherchait plus à surpasser un adversaire. Il ne rêvait ni de gloire ni de reconnaissance. Ce n'était pas davantage la peur de mourir qui le poussait à recommencer chaque matin.</p>\n<p><strong>Il éprouvait de la gratitude.</strong></p>\n<p>Envers son corps, qui lui permettait encore de tenir debout. Envers ses mains, qui n'avaient jamais abandonné le sabre. Envers cet art qui l'avait accompagné tout au long de son existence.</p>\n<p>Chaque coupe était devenue une manière de lui rendre hommage.</p>\n<p>Et lorsqu'au terme de ces dix années, Beyond redescendit enfin de la montagne, la légende raconte qu'il avait atteint le sommet de son art.</p>\n<p>Lui qui était parti dans l'espoir de devenir un meilleur sabreur serait revenu sans plus rien avoir à prouver.</p>\n<p>Il ne lui restait qu'une chose.</p>\n<p>La gratitude.</p>\n<hr/>\n<p>Enfin, c'est ainsi que Mémé me racontait son histoire.</p>\n<p>Je me souviens encore de son regard lorsqu'elle prononçait le nom de Beyond. Il y avait dans ses yeux une fierté que je n'ai jamais vraiment su comprendre.</p>\n<p>Pour elle, être un Netero signifiait quelque chose. Cela impliquait des responsabilités, des traditions, une certaine idée de l'honneur.</p>\n<p>Et surtout, cela signifiait que j'étais destiné, moi aussi, à accomplir de grandes choses.</p>\n<p>Sacrée responsabilité, vous ne trouvez pas ?</p>\n<p>D'autant qu'à cette époque, de cette famille dont elle me vantait si souvent les mérites, il ne restait plus que nous deux.</p>\n<p>Mes parents, tous deux pourfendeurs, étaient morts en me protégeant, bien avant que je puisse vraiment les connaître. Les seuls souvenirs que je possédais d’eux venaient des récits de Mémé.</p>\n<p>Ma grand-mère et moi.</p>\n<p>Ah, mais ne vous méprenez pas ! La vieille dame n'a absolument rien d'une pauvre grand-mère sans défense.</p>\n<p>Au village, on l'appelle affectueusement <strong>Mémé Turbo</strong>.</p>\n<p>Et croyez-moi, ce surnom ne lui a pas été donné pour rien !</p>\n<p>Il faudrait vraiment que quelqu'un lui rappelle qu'elle n'a plus vingt ans. Faire la course avec les jeunes du village à son âge... Un de ces jours, elle va finir par se blesser !</p>\n<p>Mais bon...</p>\n<p>Quand j’y réfléchis, peut-être que Mémé avait hérité de l’entêtement de Beyond.</p>\n<p>Dix années à s'entraîner sur une montagne, franchement...</p>\n<p>Moi, j'aurais probablement abandonné bien avant.</p>\n<p>Et pourtant, pendant longtemps, j’ai cru que c’était à cet homme que je devais ressembler.</p>\n<p>Pas étonnant que ce nom me paraisse si lourd à porter, parfois.</p>\n<p>Et pourtant, mes journées d’enfant étaient bien loin de ressembler à celles d’un sabreur de légende.</p>\n</article><div class=\"subfooter\"><a href=\"#haut\">↑ REVENIR À LA NAVIGATION</a></div></section><section class=\"chapter\" id=\"enfance\"><div class=\"chapter-banner\" style=\"background-image:url('assets/pluie-fleurs.jpg')\"><div><div class=\"chapter-index\">02 / 05</div><h2>Enfance</h2><p>Le village du Sentier Tonnerre</p></div></div><article class=\"story-text\"><p>Si vous vous attendez à me voir travailler le sabre dès mon plus jeune âge, je risque de vous décevoir.</p>\n<p>Je passais le plus clair de mon temps à observer la pluie. Ou plutôt… non. La vérité, c’est que je passais surtout mon temps à essayer de l’éviter. Je suis né dans le village du Sentier Tonnerre, un petit coin du monde surplombé par la Montagne Tonnerre. Ici, la pluie fait presque partie du décor au même titre que les chemins de terre, les rizières ou le grondement lointain du ciel. Elle tombe souvent, parfois doucement, parfois avec insistance, comme si elle refusait tout simplement de nous laisser en paix.</p>\n<p>Les anciens racontent qu’il s’agit d’une bénédiction. Selon la légende, une princesse se serait autrefois sacrifiée pour dissiper, au cœur d’un orage, les brouillards qui recouvraient le Sentier Tonnerre, permettant ainsi à nos ancêtres de s’y installer. Après sa mort, elle serait devenue l’orage lui-même. Et comme de son vivant elle veillait déjà sur les récoltes, elle continuerait encore aujourd’hui, sous la forme de cette pluie paisible, à arroser les rizières du village.</p>\n<p>Bon…</p>\n<p>Déjà, je me suis toujours demandé pourquoi une princesse se préoccupait autant de l’irrigation de nos plantations de riz. Et ensuite… je pense sincèrement qu’on aurait pu trouver un endroit un peu meilleur pour s’installer. Parce que la pluie, à longueur de journée…</p>\n<p>Enfin bref.</p>\n<p>Comme je le disais, je ne passais pas vraiment mes journées à contempler les gouttes avec un air poétique. Non. Moi, je courais entre elles. J’esquivais. Je me faufilais. Je bondissais d’un abri à l’autre comme si ma vie en dépendait, jusqu’à finir trempé, essoufflé, et parfois même affalé au sol, vaincu par mes propres gamineries.</p>\n<p>Pourquoi je faisais ça ? Pour une raison d’une importance capitale, évidemment. Je m’étais mis en tête que si j’arrivais un jour à éviter suffisamment de gouttes de pluie, alors je pourrais traverser tout le village sans encombre et rentrer avec les beignets préférés de Mémé Turbo sans qu’aucune goutte ne vienne les ramollir.</p>\n<p>Oui, dit comme ça, c’est peut-être un peu absurde. Mais à mes yeux d’enfant, c’était une mission tout à fait sérieuse. Les autres enfants se moquaient souvent de moi. Il faut dire que je n’ai jamais vraiment su comment m’intégrer à leurs groupes. Eux jouaient ensemble, riaient ensemble, se lançaient dans des jeux simples. Moi, je restais souvent dans mon coin, occupé à poursuivre des idées étranges qui n’amusaient, au fond, que moi seul.</p>\n<p>Avec le recul, je crois que j’étais déjà un peu comme ça depuis le début. Toujours à part. Toujours ailleurs. À courir après quelque chose que les autres ne voyaient pas.</p>\n<p>Quoi ?</p>\n<p>Vous voulez savoir si, au final, j’ai réussi à éviter la pluie ?</p>\n<p>Ah, ça, je préfère vous laisser le suspense. Sinon, cette histoire n’aurait plus aucun intérêt, non ?</p>\n<p>À cette époque, le tonnerre n’était pour moi qu’un bruit familier, et la pluie un adversaire de jeu. Je ne savais pas encore que je finirais par redouter le chemin du retour.</p>\n</article><div class=\"subfooter\"><a href=\"#haut\">↑ REVENIR À LA NAVIGATION</a></div></section><section class=\"chapter chapter--blood\" id=\"encore-le-tonnerre\"><div class=\"chapter-banner\" style=\"background-image:url('assets/pluie-fleurs.jpg')\"><div><div class=\"chapter-index\">03 / 05</div><h2>Encore le tonnerre</h2><p>Quand la pluie devint rouge</p></div></div><article class=\"story-text\"><p>Je venais tout juste de fêter mes seize ans lorsque l’orage qui allait bouleverser ma vie s’abattit sur le village. Et moi… j’étais encore dehors à flâner. Pourtant, je le sentais. Quelque chose clochait. Ce n’était pas seulement la pluie, ni le tonnerre, ni même le vent. C’était autre chose. Une impression étrange, diffuse, comme si l’air lui-même était devenu plus lourd, plus inquiétant. Comme si le monde retenait son souffle.</p>\n<p>Je suis rentré plus tard que d’habitude. Pour une fois, j’allais écouter les conseils de Mémé. Ne pas attraper froid. Ne pas encore l’inquiéter. Mais en revenant au village, par ce même chemin que j’empruntais chaque jour, j’ai compris que quelque chose n’allait pas. Ce sentier m’était familier. Je le connaissais par cœur. Pourtant, ce soir-là, il me semblait différent. Défiguré. Méconnaissable.</p>\n<p>Plus j’avançais, plus cette impression grandissait. Quelque chose avait changé. Je ne savais pas encore quoi.</p>\n<p>Mais je savais déjà que ce n’était pas normal.</p>\n<p>À cet âge-là, on se croit déjà grand. On s’imagine capable de tout affronter, capable de soulever des montagnes s’il le faut. Ce jour-là… J’aurais aimé en déplacer, des montagnes.</p>\n<p>Oui.</p>\n<p>J’aurais aimé déplacer des montagnes. Pour revenir plus tôt. Pour empêcher ce qui s’était passé. Pour arracher ce moment au destin. Quand je suis finalement arrivé, il n’y avait plus rien de normal.</p>\n<p>“Mémé… ?”</p>\n<p>Puis j’ai vu.</p>\n<p>Le sang.</p>\n<p>Partout.</p>\n<p>Le village entier semblait avoir été ravagé. Ce décor que j’avais toujours connu, ces maisons, ces chemins, cette pluie familière… tout avait changé. La pluie n’était plus une pluie. Elle n’arrosait plus les toits ni les rizières. Elle semblait laver du sang. “Mémé… NON ! Tout le village… Mais qu’est-ce qui s’est passé ?! Pourquoi… pourquoi tout ce sang ?! NON !!”</p>\n<p>Mémé disait toujours que j’étais un Netero. Que moi aussi, un jour, j’accomplirais de grandes choses. Mais jamais elle ne m’avait poussé vers la lame. Jamais elle ne m’avait demandé de me battre contre ce monde qui, parfois, semblait ne vivre que pour éprouver les hommes. Elle voulait simplement que je vive. Que je grandisse.</p>\n<p>Que je trouve ma propre route. Mais ce jour-là, devant ce village souillé, devant cette fresque de pluie devenue une fresque de sang… quelque chose en moi s’est brisé. Je crois que j’ai hurlé jusqu’à ne plus sentir ma gorge. Mais je n’ai pas pleuré. Pas tout de suite. J’étais incapable de pleurer. À cet instant, pour la première fois, j’ai compris quelque chose que je n’aurais jamais voulu comprendre.</p>\n<p>J’ai compris ce que Mémé ressentait quand elle pensait à mes parents. Parce que ce qui fait vraiment mal, ce n’est pas seulement de perdre quelqu’un. C’est de perdre quelqu’un qui vous a aimé. Quelqu’un que vous avez aimé en retour. C’est ça, la vraie douleur. Ce jour-là, au milieu de l’orage, un homme est apparu. Il portait un masque d’oni rouge.</p>\n<p>Je me souviens encore de cette image. De la pluie qui ruisselait sur son masque. De sa silhouette, immobile au milieu du chaos. Et de cette main qu’il m’a tendue. Il m’a dit qu’il était un ami de ma grand-mère. Il m’a dit qu’il prendrait soin de moi, désormais. Qu’il le lui avait promis. Je ne l’ai appris que bien plus tard, mais cet homme n’était pas un simple voyageur.</p>\n<p>C’était un ancien pourfendeur. Un ancien tueur de démons. Après cette nuit-là, je ne pouvais plus continuer à vivre comme si rien ne s’était passé. Je ne pouvais plus me contenter d’avancer au hasard, comme l’enfant que j’étais encore un peu.</p>\n<p>Non.</p>\n<p>Il fallait que tout cela cesse. Il fallait empêcher qu’un autre enfant vive ce que j’avais vécu. Empêcher qu’un autre Rai voie le ciel de pluie de son village se changer en orage de sang. C’est ainsi que le vieux Izanagi devint mon maître.</p>\n<p>Je croyais qu’il allait m’apprendre à me venger. Je n’avais encore aucune idée de ce qu’il allait réellement m’enseigner.</p>\n</article><div class=\"subfooter\"><a href=\"#haut\">↑ REVENIR À LA NAVIGATION</a></div></section><section class=\"chapter\" id=\"kaminari\"><div class=\"chapter-banner\" style=\"background-image:url('assets/montagne-orage.jpg')\"><div><div class=\"chapter-index\">04 / 05</div><h2>Kaminari</h2><p>Apprendre à avancer sous la pluie</p></div></div><article class=\"story-text\"><p>Lorsque je suivis Izanagi, je pensais qu’il allait m’apprendre à tuer des démons.</p>\n<p>Après tout, c'était pour cette raison que j'avais accepté de le suivre. Je voulais devenir fort, suffisamment fort pour que plus jamais personne n'ait à vivre ce que j'avais vécu.</p>\n<p>Mais les premiers jours de mon entraînement furent... comment dire ?</p>\n<p>Décevants.</p>\n<p>Pas de techniques secrètes, pas de démonstrations extraordinaires, et encore moins de combats dignes des légendes que me racontait Mémé Turbo.</p>\n<p>Non.</p>\n<p>Le vieux me faisait courir.</p>\n<p>Courir au lever du soleil, courir sur les sentiers escarpés, courir jusqu'à ce que mes jambes ne puissent plus me porter. Quand je pensais enfin pouvoir me reposer, il me demandait de recommencer.</p>\n<p>Et lorsqu'il ne me faisait pas courir, il m'apprenait à respirer.</p>\n<p>Vous imaginez ?</p>\n<p>Seize années à respirer sans problème, et voilà qu'un vieillard masqué venait m'expliquer que je ne savais même pas le faire correctement !</p>\n<p>Je commençais sérieusement à regretter ma décision.</p>\n<p>Pourtant, Izanagi ne semblait jamais agir au hasard.</p>\n<p>Il observait chacun de mes mouvements. La manière dont mes pieds touchaient le sol, dont je répartissais mon poids, dont mes épaules se crispaient lorsque la fatigue me gagnait.</p>\n<p>Il m'apprit à conserver mon équilibre sur les terrains instables, à coordonner mes déplacements avec ma respiration, à ne pas gaspiller mes forces dans des gestes inutiles.</p>\n<p id=\"kirin-start\">Puis vint le sabre.</p>\n<p>Je découvris rapidement qu'une lame n'était pas un instrument que l'on agitait simplement avec suffisamment de conviction. Il fallait apprendre à la tenir, à connaître sa portée, à contrôler son mouvement et, surtout, à savoir s'arrêter.</p>\n<p>Izanagi me répétait qu'une attaque trop précipitée pouvait être aussi dangereuse pour son auteur que pour son adversaire.</p>\n<p>Moi qui souhaitais devenir plus rapide que n'importe qui, je devais d'abord apprendre à rester immobile.</p>\n<p>Quelle ironie.</p>\n<p>Les semaines passèrent, puis les mois.</p>\n<p>Peu à peu, je compris ce que le vieux cherchait à m'enseigner.</p>\n<p><strong>Le Souffle de la Foudre.</strong></p>\n<p>Un art du sabre exigeant, reposant sur la maîtrise de la respiration, la puissance des jambes et la précision des déplacements.</p>\n<p>Contrairement à ce que son nom pouvait laisser imaginer, il ne s'agissait pas de commander aux orages. Il fallait apprendre à concentrer ses forces dans un mouvement bref et décisif.</p>\n<p>La moindre erreur dans mes appuis suffisait à compromettre une attaque. Une respiration mal maîtrisée me faisait perdre mon rythme. Une hésitation, même infime, me laissait sans défense.</p>\n<p>Je tombais souvent.</p>\n<p>Je me relevais tout aussi souvent.</p>\n<p>À force de répéter les mêmes exercices, j'avais parfois l'impression de ne plus progresser. Certains jours, mon corps semblait même refuser de m'obéir.</p>\n<p>Et ces jours-là, la colère revenait.</p>\n<p>Je repensais au village, à mes parents, à Mémé. Je revoyais ce rouge qui avait souillé les chemins de mon enfance.</p>\n<p>Je voulais aller plus vite. Frapper plus fort. Rattraper ces années d'impuissance.</p>\n<p>Mais Izanagi ne me laissait jamais poursuivre un exercice lorsque la colère prenait le dessus sur ma concentration.</p>\n<p>Un jour, alors que je protestais contre une nouvelle séance interrompue, il me demanda :</p>\n<p>— Rai, pourquoi tiens-tu tant à devenir fort ?</p>\n<p>Je lui répondis sans hésiter que je voulais empêcher d'autres massacres.</p>\n<p>Le vieux resta silencieux un moment.</p>\n<p>— Alors apprends à protéger avant d'apprendre à vaincre.</p>\n<p>Je ne crois pas avoir immédiatement compris ses paroles.</p>\n<p>Longtemps, je m'étais imaginé que devenir un grand sabreur signifiait être capable d'abattre n'importe quel adversaire.</p>\n<p>Mais à quoi servirait une victoire si, dans ma précipitation, je laissais mourir ceux que j'étais venu sauver ?</p>\n<p>Cette question finit par changer ma manière d'aborder l'entraînement.</p>\n<p>Je ne cherchais plus systématiquement à terminer chaque exercice le plus rapidement possible. Je commençais à réfléchir à mes gestes, à économiser mes forces, à reconnaître les moments où il valait mieux attendre plutôt que se précipiter.</p>\n<p>Et, chose étrange, à mesure que j'apprenais à me maîtriser, mes mouvements devenaient plus sûrs.</p>\n<p>Le temps continua de passer.</p>\n<p>Mes jambes s'endurcirent, mon souffle gagna en régularité, mes gestes devinrent plus précis. Je n'étais certainement pas devenu un maître, mais le garçon qui peinait autrefois à conserver son équilibre sur les sentiers humides pouvait désormais les parcourir avec une aisance qui l'aurait lui-même surpris.</p>\n<p>Puis, à l'approche de mes dix-huit ans, Izanagi m'emmena sur les hauteurs de la montagne du Tonnerre.</p>\n<p>Je connaissais cet endroit.</p>\n<p>Ou plutôt, je connaissais les histoires qu'on racontait à son sujet.</p>\n<p>C'était ici, quelque part sur cette montagne, que Beyond Netero aurait passé dix années de sa vie à perfectionner son art.</p>\n<p>Dix années de solitude, de répétitions et d'efforts.</p>\n<p>Je levai les yeux vers les hauteurs couvertes de nuages.</p>\n<p>Pour la première fois depuis longtemps, je repensai à cette légende sans ressentir le poids de la comparaison.</p>\n<p>Beyond avait consacré dix années à son sabre.</p>\n<p>Moi, je n'en avais même pas consacré deux.</p>\n<p>Et pourtant, je commençais à comprendre quelque chose.</p>\n<p>Peut-être que ce qui rendait son histoire si extraordinaire n'était pas simplement l'étendue de son talent, mais sa capacité à trouver du sens dans chacun de ses efforts.</p>\n<p>Je regardai mes mains.</p>\n<p>Elles avaient changé depuis le début de mon apprentissage. Les marques laissées par les entraînements témoignaient de tous ces jours où j'avais voulu abandonner, et de tous ceux où j'étais revenu malgré tout.</p>\n<p>Je pensai à mes jambes, qui m'avaient porté sur tant de sentiers. À mon souffle, que j'avais appris à écouter. À ce vieux sabre d'entraînement qui m'avait accompagné pendant des mois.</p>\n<p>Et sans vraiment savoir pourquoi, je m'inclinai.</p>\n<p>Un simple geste de reconnaissance.</p>\n<p>Pour cet art qui m'avait offert une direction lorsque je pensais avoir tout perdu.</p>\n<p>Pour Izanagi, qui avait tenu sa promesse.</p>\n<p>Et peut-être aussi pour le garçon de seize ans qui, malgré tout, avait trouvé la force de continuer.</p>\n<p>À cet instant, quelques gouttes commencèrent à tomber.</p>\n<p>Puis d'autres.</p>\n<p>Évidemment.</p>\n<p>Nous étions sur la montagne du Tonnerre. Il aurait été étonnant que le ciel nous laisse tranquilles !</p>\n<p>Je relevai la tête et souris malgré moi.</p>\n<p>Cette pluie...</p>\n<p>Toute mon enfance, j'avais essayé de l'esquiver.</p>\n<p>Je courais entre les gouttes, persuadé qu'avec suffisamment d'efforts, je pourrais un jour traverser le village sans être mouillé.</p>\n<p>Tout ça pour rapporter à Mémé Turbo ses beignets préférés.</p>\n<p>J'en avais passé, du temps, à poursuivre cet objectif ridicule.</p>\n<p>Et maintenant, après toutes ces années à apprendre à me déplacer, à courir et à contrôler mon corps...</p>\n<p>Je me retrouvais encore sous la pluie.</p>\n<p>Trempé.</p>\n<p>Décidément, certaines choses ne changent jamais.</p>\n<p>Mais cette fois, je ne cherchai pas à éviter les gouttes.</p>\n<p>Je restai simplement là, à les regarder tomber.</p>\n<p>Pendant longtemps, j'avais cru qu'il fallait devenir assez rapide pour échapper à tout ce qui pouvait nous atteindre.</p>\n<p>La douleur. La perte. Le malheur.</p>\n<p>Comme si, en courant suffisamment vite, on pouvait finir par laisser tout cela derrière soi.</p>\n<p>Quelle drôle d'idée.</p>\n<p>Personne ne peut esquiver toutes les gouttes d'un orage.</p>\n<p>Même Beyond, avec ses dix années d'entraînement, aurait probablement fini trempé !</p>\n<p>Et pourtant...</p>\n<p>On peut toujours choisir de continuer à avancer sous la pluie.</p>\n<p>Je crois que Mémé aurait bien ri en me voyant.</p>\n<p>J'aurais tellement aimé pouvoir lui raconter tout ça.</p>\n<p>Lui dire que je n'avais toujours pas réussi à vaincre cette fichue pluie, mais que j'avais enfin trouvé quelque chose qui méritait que je continue à courir.</p>\n<p>Le moment approchait désormais où il me faudrait affronter la Sélection Finale.</p>\n<p>Je ne savais pas encore ce qui m'y attendait.</p>\n<p>Je ne savais pas non plus si je serais un jour digne du nom que je portais.</p>\n<p>Mais pour une fois, cela ne m'effrayait pas autant qu'autrefois.</p>\n<p>Après tout, je n'étais pas Beyond Netero.</p>\n<p>Je n'avais pas besoin de le devenir.</p>\n<p><strong>Mon nom est Rai Netero.</strong></p>\n<p>Et je crois qu'il était grand temps de découvrir jusqu'où mes propres jambes pourraient me porter.</p>\n</article><div class=\"subfooter\"><a href=\"#haut\">↑ REVENIR À LA NAVIGATION</a></div></section><section class=\"chapter\" id=\"apres-lorage\"><div class=\"chapter-banner\" style=\"background-image:url('assets/glycines.jpg')\"><div><div class=\"chapter-index\">05 / 05</div><h2>Après l’orage</h2><p>Les sept nuits et les premières missions</p></div></div><article class=\"story-text\"><p>J'avais dix-huit ans lorsque le vieux Izanagi estima que mon entraînement était terminé.</p>\n<p>Enfin, terminé... C'est un bien grand mot. Si vous lui aviez posé la question, il vous aurait certainement répondu que j'avais encore mille choses à apprendre.</p>\n<p>Mais pour la première fois, il considérait que j'étais prêt à affronter la Sélection Finale.</p>\n<p>Sept nuits.</p>\n<p>Il me fallait survivre sept nuits sur une montagne où étaient enfermés des démons.</p>\n<p>Sept petites nuits, finalement. Après presque deux années passées à courir, à tomber et à manier le sabre sous les ordres d'un vieillard qui semblait prendre un malin plaisir à me torturer, cela ne paraissait pas si terrible.</p>\n<p>Du moins, c'est ce que je me répétais pour me rassurer.</p>\n<p>Avant mon départ, Izanagi me confia une lame et posa une main sur mon épaule.</p>\n<p>Il ne prononça pas de grand discours. Il ne me demanda pas de faire honneur à mon nom, ni de revenir couvert de gloire.</p>\n<p>Il me rappela simplement que l'objectif était de survivre.</p>\n<p>— Ne cherche pas à prouver que tu es le plus fort, Rai. Reviens vivant.</p>\n<p>Je crois que c'était sa manière de me souhaiter bonne chance.</p>\n<p>Décidément, cet homme n'avait aucun talent pour les adieux.</p>\n<hr/>\n<p>Je n'oublierai jamais les glycines.</p>\n<p>Ces fleurs magnifiques qui recouvraient les premiers versants de la montagne dégageaient un parfum presque rassurant. Il était difficile d'imaginer que, quelques pas plus loin, des créatures dévoraient des êtres humains.</p>\n<p>Pourtant, à mesure que nous progressions vers la zone de l'épreuve, les fleurs se faisaient plus rares.</p>\n<p>Et lorsque la nuit tomba, je compris enfin pourquoi Izanagi avait tant insisté sur le mot « survivre ».</p>\n<p>La première fois que j'entendis un démon, je ne vis même pas son visage.</p>\n<p>Il y eut d'abord un bruit dans les feuillages. Puis des pas, beaucoup trop rapides pour appartenir à un animal ordinaire.</p>\n<p>Je dégainai.</p>\n<p>Mon cœur battait si fort que j'avais l'impression qu'il allait couvrir le bruit de sa course.</p>\n<p>Je connaissais mes exercices. J'avais répété mes mouvements des milliers de fois. Pourtant, face à cette créature qui surgissait de l'obscurité, mes jambes me semblèrent soudain terriblement lourdes.</p>\n<p>Je compris alors qu'il existait une différence considérable entre apprendre à combattre et risquer véritablement sa vie.</p>\n<p>Le démon se jeta sur moi.</p>\n<p>Je reculai de justesse. Ses griffes déchirèrent le tissu de ma manche.</p>\n<p>J'essayai de reprendre mon souffle, de retrouver les appuis qu'Izanagi m'avait enseignés.</p>\n<p>Une inspiration.</p>\n<p>Les pieds fermement ancrés au sol.</p>\n<p>Une expiration.</p>\n<p>Puis un mouvement bref, une accélération et une coupe.</p>\n<p>Le démon ne mourut pas immédiatement. Mon premier coup manqua de précision, et je dus éviter une nouvelle attaque avant de trouver l'ouverture nécessaire pour atteindre son cou.</p>\n<p>Lorsqu'il disparut enfin, je restai un long moment immobile.</p>\n<p>J'avais réussi.</p>\n<p>Je venais de tuer mon premier démon.</p>\n<p>Je pensais ressentir une immense satisfaction, peut-être même une certaine fierté.</p>\n<p>À la place, je me sentais surtout soulagé.</p>\n<p>Soulagé d'être encore vivant.</p>\n<p>Les nuits suivantes furent plus difficiles.</p>\n<p>J'appris à ménager mes forces, à trouver des endroits où me reposer pendant la journée et à ne jamais prendre une accalmie pour une garantie de sécurité.</p>\n<p>Je croisai d'autres candidats.</p>\n<p>Certains étaient courageux. D'autres avaient peur. Quelques-uns faisaient semblant de ne pas l'être.</p>\n<p>Je me reconnaissais un peu dans chacun d'eux.</p>\n<p>Au cours de la quatrième nuit, je rencontrai un garçon blessé qui tentait désespérément de rejoindre un endroit plus sûr.</p>\n<p>Un démon le poursuivait.</p>\n<p>J'aurais pu continuer mon chemin. Après tout, personne ne nous demandait de sauver les autres candidats. Il suffisait de tenir jusqu'à la fin de l'épreuve.</p>\n<p>Mais je ne pouvais pas simplement détourner le regard.</p>\n<p>Je m'élançai pour attirer l'attention de la créature.</p>\n<p>Ce fut une mauvaise idée.</p>\n<p>Ou plutôt, une bonne idée terriblement mal exécutée.</p>\n<p>Le démon était plus rapide que je ne l'avais imaginé. En voulant l'affronter directement, je me retrouvai dans une position désavantageuse et manquai de peu de recevoir un coup fatal.</p>\n<p>Alors, au lieu de m'obstiner, je changeai de stratégie.</p>\n<p>Je profitai du terrain pour créer de la distance, puis revins aider le garçon à s'éloigner.</p>\n<p>Nous avons fui.</p>\n<p>Oui, fui !</p>\n<p>Je sais, ce n'est probablement pas l'exploit héroïque que vous attendiez.</p>\n<p>Mais nous étions deux êtres humains encore vivants au terme de cette nuit.</p>\n<p>Et cela me semblait déjà être une excellente victoire.</p>\n<hr/>\n<p>Lorsque la septième nuit prit fin, je n'avais plus grand-chose du jeune homme propre et relativement présentable qui s'était présenté à l'épreuve.</p>\n<p>Mes vêtements étaient déchirés, mes muscles me faisaient souffrir et j'avais accumulé quelques blessures dont je me serais volontiers passé.</p>\n<p>Mais j'étais vivant.</p>\n<p>Nous n'étions malheureusement pas tous revenus.</p>\n<p>Je me souviens de ces places vides, de ces visages aperçus au début de la sélection et que je ne revis jamais.</p>\n<p>Je ne connaissais même pas leurs noms.</p>\n<p>Cette pensée me troubla bien davantage que je ne l'aurais imaginé.</p>\n<p>Après notre réussite, on nous expliqua les prochaines étapes. Nous allions recevoir nos uniformes, choisir le minerai destiné à la fabrication de nos sabres Nichirin et être accompagnés d'oiseaux chargés de transmettre les missions.</p>\n<p>Nous commencions tous au rang Mizunoto.</p>\n<p>Le premier échelon.</p>\n<p>Après toutes ces épreuves, j'étais donc officiellement devenu...</p>\n<p>Le plus petit des pourfendeurs !</p>\n<p>Formidable.</p>\n<p>Je crois que Mémé Turbo aurait trouvé cela particulièrement drôle.</p>\n<hr/>\n<p>Mon premier uniforme arriva, suivi de mon propre sabre.</p>\n<p>Je me souviens de l'étrange sentiment que j'éprouvai en tenant cette lame.</p>\n<p>Ce n'était plus une arme confiée par mon maître pour un entraînement. C'était la mienne, celle avec laquelle j'allais désormais risquer ma vie.</p>\n<p>Et puis, il y eut mon corbeau.</p>\n<p>Ah, mon corbeau...</p>\n<p>Je m'étais imaginé recevoir un compagnon digne, silencieux et mystérieux.</p>\n<p>À la place, je découvris un oiseau particulièrement bruyant qui semblait persuadé que la meilleure manière de transmettre un ordre consistait à le hurler directement dans mon oreille.</p>\n<p>Je l'appréciais déjà beaucoup moins.</p>\n<p>Mais enfin, nous devions apprendre à travailler ensemble.</p>\n<p>Les premières missions furent loin de ressembler aux grandes aventures que j'avais imaginées.</p>\n<p>La plupart du temps, il fallait marcher pendant des heures, parfois des journées entières, pour atteindre des villages où l'on signalait des disparitions.</p>\n<p>Il fallait écouter les habitants, examiner les environs, attendre la nuit et tenter de comprendre où pouvait se cacher notre adversaire.</p>\n<p>Et lorsque le combat commençait enfin, tout se déroulait souvent beaucoup trop rapidement pour laisser place à la moindre réflexion héroïque.</p>\n<p>Je remportai mes premières victoires.</p>\n<p>J'accumulai également mes premières erreurs.</p>\n<p>Lors d'une mission, je me précipitai sur un démon avant d'avoir correctement évalué les lieux. Je parvins à le blesser, mais mon empressement me coûta une vilaine entaille au bras.</p>\n<p>Je dus poursuivre le combat avec une mobilité réduite, et ce fut finalement en reprenant mon calme que je trouvai l'occasion de lui trancher la tête.</p>\n<p>Les Kakushi qui me soignèrent ensuite ne furent pas particulièrement impressionnés.</p>\n<p>À vrai dire, je crois que l'un d'eux m'avait traité d'imbécile.</p>\n<p>Il n'avait probablement pas tort.</p>\n<p>D'autres missions se révélèrent beaucoup plus éprouvantes.</p>\n<p>Je découvris que certaines familles nous accueillaient avec reconnaissance, tandis que d'autres refusaient de croire à l'existence des démons, même après avoir perdu un proche.</p>\n<p>Il arrivait aussi que nous arrivions trop tard.</p>\n<p>Ces nuits-là étaient les plus difficiles.</p>\n<p>On peut s'entraîner à manier une lame.</p>\n<p>On peut renforcer ses jambes, travailler son souffle et apprendre à supporter la douleur.</p>\n<p>Mais personne ne vous apprend réellement quoi dire à quelqu'un qui vient de perdre un être cher.</p>\n<p>Je finissais généralement par rester silencieux.</p>\n<p>Parfois, je crois que c'était préférable.</p>\n<hr/>\n<p>Les années passèrent.</p>\n<p>Je parcourus des routes dont je n'avais jamais entendu parler, traversai des villages que je ne reverrais peut-être jamais et rencontrai des hommes et des femmes dont les histoires continuent encore aujourd'hui de m'accompagner.</p>\n<p>J'appris aussi à combattre aux côtés d'autres pourfendeurs.</p>\n<p>Ce fut une expérience particulièrement instructive.</p>\n<p>Il faut dire que lorsqu'on a passé une bonne partie de son enfance à jouer seul sous la pluie, on ne possède pas nécessairement les meilleures habitudes en matière de travail d'équipe.</p>\n<p>Mais j'appris.</p>\n<p>À écouter les indications d'un compagnon.</p>\n<p>À couvrir sa retraite lorsqu'il était blessé.</p>\n<p>À accepter qu'un autre porte le coup décisif.</p>\n<p>Et surtout, à comprendre qu'une mission réussie ne se mesurait pas uniquement au nombre de démons que j'avais personnellement abattus.</p>\n<p>Je me souviens d'une nuit particulièrement pluvieuse, dans un village où plusieurs habitants s'étaient retrouvés pris au piège d'une créature.</p>\n<p>Avec les autres pourfendeurs présents, nous avions réussi à repousser le démon vers une zone dégagée.</p>\n<p>Je tenais enfin une occasion de l'attaquer.</p>\n<p>Mais au moment où je m'apprêtais à m'élancer, j'aperçus un enfant qui tentait de rejoindre sa mère à découvert.</p>\n<p>Je connaissais la distance.</p>\n<p>Je savais que je pouvais tenter de frapper le démon avant qu'il ne se retourne.</p>\n<p>Mais je savais aussi ce qui arriverait si mon attaque échouait.</p>\n<p>Alors je changeai de direction.</p>\n<p>Je courus vers l'enfant.</p>\n<p>Un de mes compagnons profita de l'ouverture pour engager le démon, tandis que je mettais le garçon à l'abri.</p>\n<p>Nous parvînmes finalement à éliminer la créature.</p>\n<p>Cette nuit-là, je ne portai pas le coup final.</p>\n<p>Et, chose étrange, cela ne me dérangea pas le moins du monde.</p>\n<p>En regardant cet enfant retrouver sa mère, je repensai à ce que m'avait dit Izanagi.</p>\n<p><em>Apprends à protéger avant d'apprendre à vaincre.</em></p>\n<p>Il m'avait fallu du temps pour comprendre cette leçon.</p>\n<p>Beaucoup trop de temps, peut-être.</p>\n<p>Mais je crois que je commençais enfin à y parvenir.</p>\n<hr/>\n<p>De Mizunoto, je passai Mizunoe.</p>\n<p>Puis Kanoto, Kanoe et Tsuchinoto.</p>\n<p>Les missions s'accumulaient, les responsabilités grandissaient et, avec elles, les attentes de mes supérieurs.</p>\n<p>À chaque promotion, je pensais avoir franchi une étape importante.</p>\n<p>À chaque nouvelle mission, je découvrais tout ce qu'il me restait encore à apprendre.</p>\n<p>Je n'étais pas invincible.</p>\n<p>Je ne l'avais jamais été.</p>\n<p>J'avais connu la peur, les blessures, l'épuisement et les regrets. Il m'arrivait encore de commettre des erreurs, de douter et de me demander si j'étais véritablement à la hauteur de ce métier.</p>\n<p>Mais je continuais.</p>\n<p>Et je crois que c'était déjà quelque chose dont je pouvais être fier.</p>\n<hr/>\n<p>Aujourd'hui, j'ai vingt et un ans.</p>\n<p>Voilà maintenant trois années que j'ai survécu à la Sélection Finale.</p>\n<p>À la suite de mes dernières missions, on m'a informé que ma promotion au rang Tsuchinoe allait être officialisée.</p>\n<p>Tsuchinoe...</p>\n<p>Je ne suis pas encore certain de savoir ce que je ressens à cette idée.</p>\n<p>Une certaine fierté, bien sûr.</p>\n<p>Mais également cette impression familière qu'un nouveau poids vient de se poser sur mes épaules.</p>\n<p>Décidément, dans cette famille, nous avons un véritable talent pour nous compliquer l'existence avec des histoires d'héritage et de responsabilités.</p>\n<p>Parfois, je repense à Beyond.</p>\n<p>À ces dix années passées sur la montagne du Tonnerre, à son sabre, à sa gratitude.</p>\n<p>Je repense à Izanagi, à son vieux masque d'oni et à ses entraînements interminables.</p>\n<p>Et surtout, je repense à Mémé.</p>\n<p>Je me demande ce qu'elle penserait de moi aujourd'hui.</p>\n<p>Est-ce qu'elle serait fière ?</p>\n<p>Est-ce qu'elle trouverait encore le moyen de me gronder pour rentrer trop tard ?</p>\n<p>Probablement les deux.</p>\n<p>L'autre jour, je me suis arrêté devant une petite échoppe qui vendait des beignets.</p>\n<p>Ils ressemblaient à ceux qu'elle aimait tant.</p>\n<p>Alors j'en ai acheté deux.</p>\n<p>Un pour moi.</p>\n<p>Et un pour elle.</p>\n<p>Bon... J'ai fini par manger le sien aussi.</p>\n<p>Il aurait été dommage de le laisser refroidir, vous ne trouvez pas ?</p>\n<p>Il pleuvait ce jour-là.</p>\n<p>Une pluie légère, presque douce.</p>\n<p>J'ai levé les yeux vers le ciel et je me suis surpris à sourire.</p>\n<p>J'ignore ce que l'avenir me réserve.</p>\n<p>J'ignore si je serai un jour un sabreur aussi accompli que Beyond, ou si mon nom sera seulement oublié parmi ceux des innombrables pourfendeurs ayant consacré leur vie à protéger les autres.</p>\n<p>Mais je sais au moins une chose.</p>\n<p>Autrefois, je courais pour éviter les gouttes de pluie.</p>\n<p>Aujourd'hui, je cours pour que d'autres puissent encore les regarder tomber.</p>\n<p>Et tant que mes jambes accepteront de me porter, je continuerai.</p>\n<p>Après tout...</p>\n<p><strong>Un orage finit toujours par passer.</strong></p>\n<p><strong>Mais ce qui compte, c'est ce qu'il laisse derrière lui.</strong></p>\n</article><div class=\"subfooter\"><a href=\"#haut\">↑ REVENIR À LA NAVIGATION</a></div></section></div></main>"},"physique.html":{"title":"Physique · Rai Netero","main":"<main><section class=\"page-hero\" style=\"--hero-image:url('assets/rai-action.jpg')\"><div class=\"page-hero-content\"><div class=\"eyebrow\"><i></i>04 / Apparence</div><h1>Physique</h1><p class=\"subtitle\">Une silhouette discrète, un manteau blanc et un regard bleu sous les mèches blondes.</p></div></section><div class=\"layout\"><div class=\"card-row\"><figure class=\"poster\"><img alt=\"Illustration intégrale de Rai vêtu de blanc et bleu, avec son katana\" src=\"assets/rai-illustration.jpg\"/><figcaption>Rai Netero · Sous les glycines</figcaption></figure><div><div class=\"eyebrow\"><i></i>Silhouette &amp; apparence</div><h2>Une présence<br/>sans fracas.</h2><dl class=\"detail-list\"><div class=\"detail\"><dt>Âge</dt><dd>21 ans</dd></div><div class=\"detail\"><dt>Taille</dt><dd>1,68 m</dd></div><div class=\"detail\"><dt>Poids</dt><dd>59 kg</dd></div><div class=\"detail\"><dt>Cheveux</dt><dd>Blond clair aux reflets dorés, légèrement ébouriffés, avec des mèches tombant sur le front.</dd></div><div class=\"detail\"><dt>Yeux</dt><dd>Bleu clair, expressifs malgré un regard souvent rêveur.</dd></div><div class=\"detail\"><dt>Constitution</dt><dd>Élancée, muscles discrets développés par la course, l’endurance et le maniement du sabre.</dd></div><div class=\"detail\"><dt>Tenue</dt><dd>Vêtements bleu nuit, manteau blanc ample à capuche et ornements sobres. Sabre porté à la taille.</dd></div></dl><p class=\"body-copy\">Ses traits fins et son attitude tranquille inspirent rarement la crainte au premier regard. Ses appuis stables, ses gestes maîtrisés et sa façon de se déplacer révèlent pourtant un entraînement rigoureux.</p></div></div><div class=\"separator\"></div><div class=\"intro-grid\"><div class=\"intro-panel\"><div class=\"eyebrow\">En mouvement</div><h2>Le calme ne dure qu’un instant.</h2><p>Le manteau blanc accentue visuellement la rapidité de ses gestes. Les bleus de sa tenue et la clarté de son regard contrastent avec les paysages sombres de son histoire.</p><p>Son manteau blanc aux pans souples accompagne chaque déplacement, tandis que les pièces plus sombres de sa tenue soulignent sa silhouette légère. Même au repos, il conserve souvent cette posture légèrement prête à repartir.</p></div><figure class=\"poster\"><img alt=\"Rai Netero en position dynamique\" src=\"assets/rai-action.jpg\"/><figcaption>Rai Netero · En mouvement</figcaption></figure></div><div class=\"subfooter\"><a href=\"competences.html\">SUIVANT — SES COMPÉTENCES ↗</a></div></div></main>"},"competences.html":{"title":"Compétences · Rai Netero","main":"<main><section class=\"page-hero\" style=\"--hero-image:url('assets/montagne-orage.jpg')\"><div class=\"page-hero-content\"><div class=\"eyebrow\"><i></i>05 / Arts du sabre</div><h1>Compétences</h1><p class=\"subtitle\">Le Souffle de la Foudre : appuis, respiration et décision.</p></div></section><div class=\"layout\"><div class=\"two-col\"><div class=\"body-copy\"><div class=\"eyebrow\"><i></i>雷の呼吸 · Kaminari no Kokyū</div><h2>Souffle<br/>de la Foudre.</h2><p>Rai a appris le combat au sabre auprès du vieux Izanagi. Son entraînement s’est construit autour de la respiration, du renforcement des jambes, de la précision des appuis et de l’économie des gestes.</p><p>Ce Souffle n’invoque pas la foudre : sa puissance vient de la respiration, de la maîtrise du corps et de la vivacité des frappes.</p><p>Son style privilégie la maîtrise de l’instant décisif plutôt que l’agitation permanente. Il apprend à ne pas confondre vitesse et précipitation.</p></div><figure class=\"poster\"><img alt=\"Rai Netero et le kanji de la Foudre\" data-gif-portrait=\"\" src=\"assets/portrait-logo.png\"/><figcaption>雷 — foudre</figcaption></figure></div><div class=\"info-grid\"><div class=\"info-item\"><div class=\"label\">Rang</div><strong>Tsuchinoe</strong></div><div class=\"info-item\"><div class=\"label\">Capacités physiques</div><strong>Niveau II</strong></div><div class=\"info-item\"><div class=\"label\">Sens améliorés</div><strong>Niveau II</strong></div></div><section aria-labelledby=\"foudre-formes\" class=\"forms-showcase\">\n<div class=\"form-heading\"><div class=\"eyebrow\"><i></i>雷の呼吸 · Les formes du Souffle</div>\n<h2 id=\"foudre-formes\">Les mouvements<br/><em>de la Foudre.</em></h2>\n<p>Une discipline de l’instant : un pas juste, une respiration maîtrisée et une lame qui ne laisse aucun geste au hasard.</p></div>\n<div class=\"forms-grid\"><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">I</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Première forme</span>\n<h3>Flash de l’Éclair</h3><div class=\"form-japanese\">Ichi no kata · Hekireki Issen</div>\n<p>Le sabre jaillit du fourreau à grande vitesse. Le mouvement s’achève sur une coupe oblique, de bas en haut.</p>\n</div>\n</article><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">I+</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Variante de la première forme</span>\n<h3>Flash de l’Éclair — Six Pliés</h3><div class=\"form-japanese\">Ichi no kata · Hekireki Issen, Rokuren</div>\n<p>Une frappe verticale descendante précède un déplacement latéral : l’épéiste surprend l’adversaire par une coupe horizontale.</p>\n</div>\n</article><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">II</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Deuxième forme</span>\n<h3>Danse de la Tempête de Foudre</h3><div class=\"form-japanese\">Ni no kata · Shūra Enbu</div>\n<p>Trois coupes rapides se succèdent, dessinant une trajectoire en éclair : oblique descendante, remontante, puis de nouveau descendante.</p>\n</div>\n</article><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">III</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Troisième forme</span>\n<h3>Foudre en Six Parties</h3><div class=\"form-japanese\">San no kata · Roku Hon no Ikazuchi</div>\n<p>Six frappes réparties dans des directions différentes s’enchaînent dans le sens inverse des aiguilles d’une montre.</p>\n</div>\n</article><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">IV</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Quatrième forme</span>\n<h3>Tonnerre lointain</h3><div class=\"form-japanese\">Shi no kata · hi no kata Enrai</div>\n<p>Des quarts de tour permettent de contourner l’adversaire. Le sabreur multiplie les attaques pour le déstabiliser et chercher une faille dans sa garde.</p>\n</div>\n</article><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">V</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Cinquième forme</span>\n<h3>Éclair de chaleur</h3><div class=\"form-japanese\">Go no kata · Netsu Kairai</div>\n<p>Un pas sec vers l’avant accompagne une frappe ascendante dont le mouvement étend la portée pour surprendre la cible.</p>\n</div>\n</article><article class=\"form-card\">\n<div aria-hidden=\"true\" class=\"form-number\">VI</div>\n<div class=\"form-details\"><span class=\"form-eyebrow\">Sixième forme</span>\n<h3>Rumble et Flash</h3><div class=\"form-japanese\">Roku no kata · Dengō Raigō</div>\n<p>Le haut et le bas du corps se désynchronisent avant une coupe horizontale particulièrement difficile à anticiper. C’est le mouvement le plus exigeant à maîtriser en situation réelle.</p>\n</div>\n</article></div>\n</section><div class=\"separator\"></div><div class=\"two-col\"><div class=\"body-copy\"><h3>Arme</h3><p>Un katana Nichirin reçu après la Sélection Finale. Rai privilégie un sabre classique et maniable, adapté aux déplacements rapides et aux frappes précises.</p></div><div class=\"body-copy\"><h3>Capacités exceptionnelles</h3><p>Rai n’a éveillé ni Marque du Pourfendeur ni Monde Transparent. Sa lame n’est pas cramoisie.</p></div></div><div class=\"subfooter\"><a href=\"index.html\">RETOUR À L’ACCUEIL ↗</a></div></div></main>"}};

/* Navigation du site : seules les sections centrales changent.
   Le lecteur reste monté dans le DOM et continue à jouer pendant tous les changements de rubrique. */
(function(){
  const pages=window.RAI_PAGES||{};
  const nav=document.querySelector('.site-nav');
  const menu=document.querySelector('.nav-toggle');
  const prog=document.querySelector('.page-progress');
  let ticking=false;
  const updateProgress=()=>{
    if(!prog)return;
    const max=document.documentElement.scrollHeight-window.innerHeight;
    prog.style.width=(max>0?Math.max(0,Math.min(100,window.scrollY/max*100)):100)+'%';
    ticking=false;
  };
  if(menu){
    menu.addEventListener('click',()=>{
      const open=nav.classList.toggle('is-open');
      menu.setAttribute('aria-expanded',String(open));
    });
  }
  window.addEventListener('scroll',()=>{
    if(!ticking){ticking=true;window.requestAnimationFrame(updateProgress)}
  },{passive:true});
  window.addEventListener('resize',updateProgress);
  const restorePortraits=()=>{
    document.querySelectorAll('[data-gif-portrait]').forEach(img=>{
      img.src='assets/rai-portrait.gif';
    });
  };
  restorePortraits();
  const fileOf=(url)=>url.pathname.split('/').pop()||'index.html';
  let activeFile=fileOf(new URL(location.href));
  window.RAI_CURRENT_PAGE=activeFile;
  const inSameDirectory=(url)=>url.origin===location.origin &&
    url.pathname.slice(0,url.pathname.lastIndexOf('/')+1)===location.pathname.slice(0,location.pathname.lastIndexOf('/')+1);
  const scrollToHash=(hash)=>{
    if(hash){
      let id;try{id=decodeURIComponent(hash.slice(1))}catch(e){id=hash.slice(1)}
      const target=document.getElementById(id);
      if(target){target.scrollIntoView({block:'start',behavior:'auto'});return}
    }
    window.scrollTo({top:0,left:0,behavior:'auto'});
  };
  function render(url){
    const name=fileOf(url);
    if(!pages[name])return false;
    const newMain=document.createElement('template');
    newMain.innerHTML=pages[name].main.trim();
    const next=newMain.content.querySelector('main');
    const old=document.querySelector('main');
    if(!old||!next)return false;
    old.replaceWith(next);
    activeFile=name;
    window.RAI_CURRENT_PAGE=name;
    document.title=pages[name].title;
    document.querySelectorAll('.nav-items a').forEach(link=>{
      const current=new URL(link.href,location.href);
      if(fileOf(current)===name)link.setAttribute('aria-current','page');
      else link.removeAttribute('aria-current');
    });
    nav?.classList.remove('is-open');
    menu?.setAttribute('aria-expanded','false');
    restorePortraits();
    requestAnimationFrame(()=>{scrollToHash(url.hash);updateProgress();window.dispatchEvent(new CustomEvent("rai:page-changed"));});
    return true;
  }
  document.addEventListener('click',event=>{
    if(event.defaultPrevented||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
    const a=event.target.closest('a[href]');
    if(!a||a.hasAttribute('download')||a.target&&a.target!=='_self')return;
    const href=(a.getAttribute('href')||'').trim();
    if(!href)return;
    let url;
    try{
      url=href.startsWith('#')
        ? new URL(activeFile+href,location.href)
        : new URL(href,location.href);
    }catch(e){return}
    if(!inSameDirectory(url)||!pages[fileOf(url)])return;
    // Preserve native same-page anchors (Héritage, Enfance, ...)
    const samePage=fileOf(url)===activeFile;
    if(samePage && url.hash){
      event.preventDefault();
      try{history.pushState({raiPage:true},'',url.pathname+url.search+url.hash)}catch(e){}
      scrollToHash(url.hash);
      window.dispatchEvent(new CustomEvent('rai:page-changed'));
      nav?.classList.remove('is-open');
      menu?.setAttribute('aria-expanded','false');
      return;
    }
    event.preventDefault();
    if(samePage && !url.hash){scrollToHash('');return}
    try{history.pushState({raiPage:true},'',url.pathname+url.search+url.hash)}catch(e){}
    render(url);
  });
  window.addEventListener('popstate',()=>render(new URL(location.href)));
  updateProgress();
  // When a chapter is opened from a copied link, bring it into view on initial load.
  if(location.hash){requestAnimationFrame(()=>{scrollToHash(location.hash);window.dispatchEvent(new CustomEvent('rai:page-changed'));});}
})();

/* Izanami / Kirin : deux pistes actives sous un lecteur persistant.
   Les deux appels play() partent du clic utilisateur : la transition ne doit
   jamais créer une nouvelle tentative d'autoplay pendant la navigation. */
(function(){
  const izanami=document.getElementById('rai-audio');
  if(!izanami)return;
  izanami.src='assets/izanami.mp3';
  izanami.loop=true;
  const kirin=document.createElement('audio');
  kirin.id='rai-audio-kirin';
  kirin.src='assets/kirin.mp3';
  kirin.preload='metadata';
  kirin.loop=true;
  kirin.setAttribute('playsinline','');
  izanami.after(kirin);
  const tracks={izanami:{name:'Izanami',audio:izanami},kirin:{name:'Kirin',audio:kirin}};
  const byId=id=>document.getElementById(id);
  const toggle=byId('music-toggle'),panel=byId('music-panel'),close=byId('music-close');
  const play=byId('music-play'),stop=byId('music-stop'),mute=byId('music-mute');
  const seek=byId('music-seek'),vol=byId('music-volume'),volLabel=byId('music-volume-label'),time=byId('music-time');
  const title=panel.querySelector('#music-track-title');
  const modeButtons=[...document.querySelectorAll('[data-music-mode]')];
  const key='rai-netero-music-v13-';
  function read(k,fallback){try{return sessionStorage.getItem(key+k)??fallback}catch{return fallback}}
  function write(k,value){try{sessionStorage.setItem(key+k,String(value))}catch{}}
  const toTime=x=>{const s=Number.isFinite(x)?Math.floor(x):0;return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`};
  const show=open=>{panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open))};
  toggle.addEventListener('click',()=>show(panel.hidden));
  close.addEventListener('click',()=>show(false));
  let userVolume=Math.max(0,Math.min(1,Number(read('volume','.35'))));
  let isMuted=read('muted','false')==='true';
  let mode='auto';
  let current='izanami';
  let fadeFrame=null;
  let tryingToPlay=false;
  const positions={izanami:Number(read('position-izanami','0'))||0,kirin:Number(read('position-kirin','0'))||0};
  function playing(){return !izanami.paused || !kirin.paused}
  function activeAudio(){return tracks[current].audio}
  function setVolumes(){
    izanami.volume=current==='izanami'&&!isMuted?userVolume:0;
    kirin.volume=current==='kirin'&&!isMuted?userVolume:0;
  }
  function cancelFade(){if(fadeFrame!==null){cancelAnimationFrame(fadeFrame);fadeFrame=null}}
  function savePositions(){
    for(const [id,info] of Object.entries(tracks)){
      if(Number.isFinite(info.audio.currentTime)){
        positions[id]=info.audio.currentTime;write('position-'+id,positions[id]);
      }
    }
  }
  function restorePosition(id){
    const a=tracks[id].audio;
    const p=positions[id];
    if(p>0&&Number.isFinite(a.duration)&&a.duration>0){try{a.currentTime=Math.min(p,a.duration-.1)}catch{}}
  }
  for(const id of Object.keys(tracks)){
    const a=tracks[id].audio;
    a.addEventListener('loadedmetadata',()=>{restorePosition(id);if(id===current)refreshTime()});
    a.addEventListener('timeupdate',()=>{positions[id]=a.currentTime;write('position-'+id,a.currentTime);if(id===current)refreshTime()});
    a.addEventListener('play',refreshPlay);
    a.addEventListener('pause',refreshPlay);
    a.addEventListener('ended',()=>{positions[id]=0;write('position-'+id,'0')});
  }
  function refreshVolume(){
    vol.value=String(Math.round(userVolume*100));
    volLabel.textContent=Math.round(userVolume*100)+' %';
    mute.textContent=isMuted||userVolume===0?'×':'♪';
    mute.setAttribute('aria-label',isMuted?'Rétablir le son':'Couper le son');
  }
  function refreshPlay(){
    const on=playing();
    play.textContent=on?'Ⅱ':'▶';
    play.setAttribute('aria-label',on?'Mettre en pause':'Lire la musique');
    toggle.classList.toggle('music-is-playing',on);
  }
  function refreshTime(){
    const a=activeAudio(),dur=a.duration;
    time.textContent=toTime(a.currentTime)+' / '+toTime(dur);
    seek.value=Number.isFinite(dur)&&dur>0?String(Math.round(a.currentTime/dur*1000)):'0';
  }
  function refreshTheme(){
    title.textContent=tracks[current].name;
    modeButtons.forEach(b=>{const selected=b.dataset.musicMode===mode;b.classList.toggle('is-active',selected);b.setAttribute('aria-pressed',String(selected))});
    refreshTime();
  }
  function getAutoTheme(){
    const page=window.RAI_CURRENT_PAGE||location.pathname.split('/').pop()||'index.html';
    if(page!=='histoire.html')return 'izanami';
    const marker=document.getElementById('kirin-start');
    return marker&&marker.getBoundingClientRect().top<=innerHeight*.55?'kirin':'izanami';
  }
  function setTrack(next,{instant=false}={}){
    if(!tracks[next]||next===current)return;
    cancelFade();
    const a=tracks[current].audio,b=tracks[next].audio;
    current=next;
    refreshTheme();
    if(!playing()||instant){setVolumes();return}
    const fromA=a.volume,fromB=b.volume,target=isMuted?0:userVolume,start=performance.now(),duration=650;
    const frame=now=>{
      const t=Math.min(1,(now-start)/duration),soft=t*t*(3-2*t);
      a.volume=Math.max(0,fromA*(1-soft));
      b.volume=Math.max(0,fromB+(target-fromB)*soft);
      if(t<1)fadeFrame=requestAnimationFrame(frame);else {fadeFrame=null;setVolumes()}
    };
    fadeFrame=requestAnimationFrame(frame);
  }
  function syncMode(){if(mode==='auto')setTrack(getAutoTheme())}
  let frameRequested=false;
  function checkScene(){if(frameRequested)return;frameRequested=true;requestAnimationFrame(()=>{frameRequested=false;syncMode()})}
  // Start both streams from the *same direct click*. Changing pages merely
  // crossfades volumes, never replaces src, calls load() or restarts playback.
  function startBoth(){
    if(tryingToPlay)return;
    tryingToPlay=true;
    syncMode();
    cancelFade();setVolumes();
    const promises=[izanami.play(),kirin.play()];
    Promise.allSettled(promises).then(results=>{
      tryingToPlay=false;
      if(results.some(x=>x.status==='rejected')){
        show(true);
        console.warn('Rai music: one browser audio stream could not start',results);
      }
      refreshPlay();
    });
    refreshPlay();
  }
  play.addEventListener('click',()=>{
    if(playing()){
      izanami.pause();kirin.pause();cancelFade();setVolumes();refreshPlay();
    }else startBoth();
  });
  stop.addEventListener('click',()=>{
    cancelFade();
    for(const [id,info] of Object.entries(tracks)){
      info.audio.pause();info.audio.currentTime=0;positions[id]=0;write('position-'+id,'0');
    }
    setVolumes();refreshTime();refreshPlay();
  });
  mute.addEventListener('click',()=>{isMuted=!isMuted;write('muted',isMuted);cancelFade();setVolumes();refreshVolume()});
  vol.addEventListener('input',()=>{userVolume=Number(vol.value)/100;isMuted=false;write('volume',userVolume);write('muted','false');cancelFade();setVolumes();refreshVolume()});
  seek.addEventListener('input',()=>{
    const a=activeAudio();if(Number.isFinite(a.duration)&&a.duration>0){a.currentTime=a.duration*Number(seek.value)/1000;refreshTime()}
  });
  modeButtons.forEach(button=>button.addEventListener('click',()=>{
    mode=button.dataset.musicMode;
    setTrack(mode==='auto'?getAutoTheme():mode);
    refreshTheme();
  }));
  window.addEventListener('pagehide',savePositions);
  window.addEventListener('scroll',checkScene,{passive:true});
  window.addEventListener('resize',checkScene);
  window.addEventListener('rai:page-changed',checkScene);
  setVolumes();refreshVolume();refreshTheme();refreshPlay();checkScene();
})();
